/**
 * base-frente-check — hook GLOBAL de SessionStart da família -base.
 *
 * INTENÇÃO: abrir o chat dentro da worktree JÁ é o gesto — a sessão nasce sabendo em que frente
 * está, quem é o dono (chat_id), se a branch está atrasada, e se falta o /ligar-frente-base.
 * Instrução é a camada mais fraca; este hook faz o que o Rafael teria que lembrar de pedir.
 *
 * CONTRATO:
 *   - A raiz das worktrees vem do `esteira.json` (subindo a partir do cwd) — nunca de constante.
 *     Sem `esteira.json` → silêncio absoluto. Fora de `<cfg.wt_root>/<slug>` → silêncio.
 *   - `<cfg.wt_root>/_*` é RÉPLICA (auditoria, descartável): silêncio e NADA gravado (issue #12).
 *   - Grava <git-dir>/claude-session-id e preenche `chat_id` vazio do registro (nunca sobrescreve).
 *   - Frescor: fetch best-effort (7 s) e "N commits atrás de <remote>/<base>".
 *   - Qualquer erro → silêncio e exit 0. NUNCA quebrar o boot da sessão.
 *
 * Instalação: `install.ps1 -Hooks -Apply` (aponta ~/.claude/settings.json para DENTRO do kit).
 */
import { readFileSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { getEsteira, registroDaFrente } from '../scripts/lib/esteira.mjs';
import { sanitizeSessionId, gravarSessionId, preencherChatIdArquivoSeVazio, lerCampoDeTexto } from '../scripts/lib/frente-registro.mjs';
import { papelDoCwd } from './lib/base-hook-lib.mjs';

// execFileSync com array: remote/branch vêm do esteira.json do repo — nunca passam por shell.
function git(args, cwd, timeout = 5000) {
  try { return execFileSync('git', args, { cwd, encoding: 'utf-8', stdio: ['ignore', 'pipe', 'ignore'], timeout }).trim(); }
  catch { return ''; }
}

try {
  const cwd = (process.env.CLAUDE_PROJECT_DIR || process.cwd()).replaceAll('\\', '/');

  let cfg;
  try { cfg = getEsteira(cwd); } catch { process.exit(0); }          // não é projeto da esteira
  if (/[OUTRO-PROJETO]/i.test(cfg.repoRoot)) process.exit(0);

  if (papelDoCwd(cfg, cwd) !== 'frente') process.exit(0);          // integração, réplica (_*) e auditoria: silêncio (issue #18)
  const raiz = cfg.wtRoot;
  const slug = cwd.slice(raiz.length + 1).split('/')[0];
  if (!slug) process.exit(0);

  const worktree = `${raiz}/${slug}`;
  if (cfg.repoRoot.toLowerCase() !== worktree.toLowerCase()) {
    console.log(`### Frente \`${slug}\` — incoerência: o esteira.json lido está em \`${cfg.repoRoot}\`, não na raiz da worktree \`${worktree}\`. Confira antes de trabalhar.`);
    process.exit(0);
  }

  // session_id chega no stdin do hook (JSON, `session_id`) — não há env var.
  let sessionId = '';
  try { sessionId = sanitizeSessionId(JSON.parse(readFileSync(0, 'utf-8')).session_id) || ''; } catch { /* ignora-de-proposito: fail-soft */ }

  const gitDir = git(['rev-parse', '--absolute-git-dir'], worktree);
  const branch = git(['rev-parse', '--abbrev-ref', 'HEAD'], worktree);
  if (sessionId && gitDir) gravarSessionId(gitDir, sessionId);

  let fetched = false;
  try { execFileSync('git', ['fetch', cfg.remote, cfg.branchBase], { cwd: worktree, timeout: 7000, stdio: 'ignore' }); fetched = true; } catch { /* ignora-de-proposito: offline */ }
  const n = git(['rev-list', '--count', `HEAD..${cfg.remote}/${cfg.branchBase}`], worktree);
  const behind = /^\d+$/.test(n) ? parseInt(n, 10) : null;

  const registro = registroDaFrente(cfg, slug);
  const L = [];
  L.push(`### Frente \`${slug}\` · projeto \`${cfg.projeto}\` · repo \`${cfg.repo}\` · branch \`${branch || '?'}\``);
  if (branch && branch !== `claude/${slug}`) L.push(`⚠️ pasta \`${slug}\` ≠ branch \`${branch}\`. A LEI 73 exige igualdade — confira antes de editar.`);
  if (behind && behind > 0) L.push(`⚠️ **FRESCOR:** ${behind} commit(s) ATRÁS de \`${cfg.remote}/${cfg.branchBase}\`${fetched ? '' : ' (fetch falhou; pode estar defasado)'}. Integre antes de editar ou julgar diffs: \`git merge ${cfg.remote}/${cfg.branchBase}\`.`);
  else if (behind === 0) L.push(`frescor: em dia com \`${cfg.remote}/${cfg.branchBase}\`.`);

  if (!existsSync(registro)) {
    L.push('', `Esta worktree não tem \`_frentes/${slug}.md\`. Foi aberta fora do \`npm run frente:abrir\`. **Não crie o arquivo à mão** — é território do script. Se for trabalhar de verdade, rode \`/ligar-frente-base\` mesmo assim; sessão que só lê/responde é ISENTA.`);
    console.log(L.join('\n')); process.exit(0);
  }

  if (sessionId) {
    const st = preencherChatIdArquivoSeVazio(registro, sessionId);
    if (st === 'preenchido') L.push('chat_id: preenchido com esta sessão (dono da frente). Commite o registro junto com o trabalho.');
    else if (st === 'ja-preenchido') L.push('chat_id: já registrado (o primeiro dono continua o dono).');
  }

  const texto = readFileSync(registro, 'utf8');
  const status = lerCampoDeTexto(texto, 'status');
  const ligada = lerCampoDeTexto(texto, 'github_frente');
  const label = `${cfg.prefixoFrente}${slug}`;

  if (status && status !== 'aberta') { L.push(`status: \`${status}\` — esta frente já pousou; nada a cobrar.`); console.log(L.join('\n')); process.exit(0); }

  if (ligada) {
    L.push('', `🔗 ligada: label **\`${ligada}\`** em \`${cfg.repo}\`. Carregue \`Skill(modelo-base)\` se ainda não carregou nesta sessão.`, '',
      '```bash', `gh issue list --repo ${cfg.repo} --label "${ligada}" --state open`, '```', '',
      '**Regra de foco:** trabalhe nas issues desta frente. Não traga pendência de outra — a menos que bloqueie esta ou o dono peça. Olhar amplo tem 4 momentos: abrir a frente, capturar achado, antes de mergear, ao fechar.', '',
      `⚠️ Bloqueio no GitHub não aparece sozinho: é menção \`#N\` no corpo + label \`bloqueado\`. Ao pegar uma issue, \`gh issue list --repo ${cfg.repo} --state open --search "#<n>"\`.`, '',
      `Diário da coordenação: issue #${cfg.coordenacaoIssue || '(ainda não criada)'}. Ao encerrar: \`/6-fechar-frente-base\` (= \`/feito-base\` → \`/pousar-frente-base\` → \`/gravar-base\` → \`/fechar-base\`).`);
  } else {
    L.push('', `### 🔗 Frente NÃO está ligada ao GitHub`, '',
      `O registro existe, mas \`github_frente\` está vazio — falta o quinto termo da LEI 73.`, '',
      `**Se esta sessão vai trabalhar nesta frente:** rode \`/ligar-frente-base\` AGORA (cria a label \`${label}\` em \`${cfg.repo}\`, grava o vínculo e o \`app_session_id\`, e carrega o \`modelo-base\`).`, '',
      `**Se é só leitura, pergunta ou consulta:** ignore — a LEI 73 isenta.`);
  }
  console.log(L.join('\n'));
} catch { /* ignora-de-proposito: silencioso por contrato */ }
process.exit(0);

